import * as THREE from './vendor/three.module.js';
import {pointInside,nearestOnSegment,project} from './core.js';

const norm=s=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,'').replace(/\s+/g,' ').trim();
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const materials=new Map();
function material(color,rough=.9){const key=color+','+rough;if(!materials.has(key))materials.set(key,new THREE.MeshStandardMaterial({color,roughness:rough}));return materials.get(key);}
function box(g,color,x,y,z,w,h,d,rough=.9){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material(color,rough));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;g.add(m);return m;}
function column(g,color,x,y,z,r,h){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r*1.04,h,12),material(color));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;g.add(m);return m;}
function plane(g,color,x,y,z,w,d){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),material(color));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);m.receiveShadow=true;g.add(m);return m;}
function cornice(g,color,y,z,w,d=.45){box(g,color,0,y,z,w,.28,d);}
function cross(g,x,y,z,s=.6){box(g,'#655f51',x,y,z,.16*s,1.6*s,.16*s);box(g,'#655f51',x,y+.28*s,z,.9*s,.15*s,.16*s);}
function plaque(g,text,x,y,z,w=7,h=1.1){if(typeof document==='undefined')return;const c=document.createElement('canvas');c.width=768;c.height=128;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#e5d8bc';ctx.font='700 58px Georgia,serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,c.width/2,c.height/2);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:tex,transparent:true,toneMapped:false}));m.position.set(x,y,z);g.add(m);return m;}
function rose(g,x,y,z,r){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.14,8,24),material('#d9ccb2'));ring.position.set(x,y,z);ring.rotation.x=Math.PI/2;g.add(ring);const disc=new THREE.Mesh(new THREE.CircleGeometry(r*.78,24),material('#456067',.7));disc.position.set(x,y,z+.02);g.add(disc);}
function frame(b){const p=b?.p||[];let edge=null,best=0;for(let i=0;i<p.length;i++){const a=p[i],q=p[(i+1)%p.length],d=Math.hypot(q[0]-a[0],q[1]-a[1]);if(d>best){best=d;edge=[a,q];}}if(!edge)return null;const [a,q]=edge,dx=(q[0]-a[0])/best,dz=(q[1]-a[1])/best,px=-dz,pz=dx,cx=Number.isFinite(b.cx)?b.cx:(a[0]+q[0])/2,cz=Number.isFinite(b.cz)?b.cz:(a[1]+q[1])/2;let minP=Infinity,maxP=-Infinity;for(const v of p){const vdx=v[0]-cx,vdz=v[1]-cz,s=vdx*px+vdz*pz;minP=Math.min(minP,s);maxP=Math.max(maxP,s);}return {cx,cz,yaw:Math.atan2(dx,dz),length:best,width:Math.max(8,maxP-minP)};}
function findBuilding(data,aliases){const names=aliases.map(norm);let best=null,bestScore=-Infinity;for(const b of data.buildings||[]){const n=norm(b.n);if(!n)continue;const hit=names.some(a=>n===a||n.includes(a));if(!hit)continue;const area=Math.max(1,(b.maxX-b.minX)*(b.maxZ-b.minZ));const exact=names.includes(n)?100000:0,score=exact+area;if(score>bestScore){best=b;bestScore=score;}}return best;}
function setAuthored(b){if(!b)return;b.authoredLandmark=true;b.modelActive=true;}
function windowRows(g,w,l,h,frontZ){for(const y of [5.2,8.2])for(let x=-w*.38;x<=w*.38;x+=Math.max(3.2,w/6)){box(g,'#456066',x,y,frontZ,w*.055,1.65,.12,.55);box(g,'#d8c9ac',x,y-1.03,frontZ+.02,w*.08,.16,.16);}}
function arcadeLocal(g,w,z,y=0,depth=3.4,count=7,color='#d8c9ae'){const span=w/(count+1);box(g,'#b8a583',0,y+4.15,z-depth*.5,w+.7,.36,depth+.5);for(let i=0;i<=count;i++){const x=-w/2+i*w/count;column(g,color,x,y+2,z-depth*.88,.25,4);box(g,color,x,y+3.93,z-depth*.46,.48,.3,depth*.92);}return g;}
function pedrocchi(data,terrain){const b=findBuilding(data,['Caffè Pedrocchi','Cafe Pedrocchi','Pedrocchi']);const fallback=project(45.4079,11.8778),f=b?frame(b):{cx:fallback.x,cz:fallback.z,yaw:.04,width:29,length:43};if(!f)return new THREE.Group();setAuthored(b);const g=new THREE.Group();g.userData.poi='pedrocchi';g.userData.name='Caffè Pedrocchi';g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,24,36),l=clamp(f.length,34,52),h=11.5;box(g,'#d9d0bc',0,h/2,0,w,h,l);box(g,'#c8b895',0,h+.35,0,w+1,.7,l+1);box(g,'#9a7b61',0,h+.8,0,w+.45,.22,l+.45);windowRows(g,w,l,h,l/2+.08);arcadeLocal(g,w*.92,l/2+.3,0,4,8,'#ded4c0');for(const side of [-1,1]){const loggia=new THREE.Group();loggia.position.set(side*(w/2+2.2),0,l*.16);g.add(loggia);box(loggia,'#d8cdb7',0,4.15,0,4.3,.34,8);for(const z of [-3,-1,1,3])column(loggia,'#dcd1bb',0,2,z,.28,4);box(loggia,'#c0ae8d',0,.2,0,4.8,.35,8.6);}plaque(g,'PEDROCCHI',0,9.6,l/2+.2,8,1.25);g.userData.centre={x:f.cx,z:f.cz};return g;}
function moroni(data,terrain){const b=findBuilding(data,['Palazzo Moroni','Municipio di Padova','Municipio']);const f=b?frame(b):{cx:-45,cz:-60,yaw:0,width:34,length:48};setAuthored(b);const g=new THREE.Group();g.userData.poi='palazzo-moroni';g.userData.name='Palazzo Moroni · Municipio';g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,24,44),l=clamp(f.length,30,58),h=14;box(g,'#cdb995',0,h/2,0,w,h,l);box(g,'#b59b77',0,1.1,l/2+.1,w*.95,2.1,.25);for(let x=-w*.36;x<=w*.36;x+=Math.max(3.6,w/6)){box(g,'#42585c',x,7.2,l/2+.16,1.35,2.2,.12);box(g,'#ddcdb0',x,5.8,l/2+.17,1.7,.18,.16);}box(g,'#4d463c',0,2.6,l/2+.2,3.4,5.2,.16);for(const side of [-1,1]){column(g,'#d8c9aa',side*2.4,3,l/2+.35,.32,6);box(g,'#d8c9aa',side*2.4,6.15,l/2+.35,.58,.28,.58);}cornice(g,'#d8c9aa',11.2,l/2+.18,w*.96,.38);plaque(g,'MUNICIPIO',0,10.2,l/2+.22,7,1.1);g.userData.centre={x:f.cx,z:f.cz};return g;}
function palazzoBo(data,terrain){const b=findBuilding(data,['Palazzo del Bo','Palazzo Bo','Università degli Studi di Padova','Universita degli Studi di Padova']);const fallback=project(45.4071,11.8772),f=b?frame(b):{cx:fallback.x,cz:fallback.z,yaw:.02,width:36,length:55};setAuthored(b);const g=new THREE.Group();g.userData.poi='palazzo-bo';g.userData.name='Palazzo del Bo · Università';g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,28,48),l=clamp(f.length,38,64),h=13;box(g,'#c8b18d',0,h/2,0,w,h,l);box(g,'#aa8e6d',0,h+.3,0,w+.7,.6,l+.7);for(let x=-w*.38;x<=w*.38;x+=Math.max(3.5,w/7)){box(g,'#42575b',x,8.1,l/2+.16,1.25,2,.12);box(g,'#d8c6a6',x,6.9,l/2+.18,1.55,.16,.16);}box(g,'#4b4438',0,2.7,l/2+.2,3.1,5.4,.16);arcadeLocal(g,w*.82,l/2+.34,0,3.6,7,'#d7c7aa');plaque(g,'UNIVERSITÀ · BO',0,10.7,l/2+.23,10,1.15);g.userData.centre={x:f.cx,z:f.cz};return g;}
function piazzaSignori(terrain){const g=new THREE.Group();g.userData.poi='piazza-signori-complete';g.userData.name='Piazza dei Signori';const y=terrain.elevation(-282,-140);plane(g,'#b9ac91',-282,y+.055,-140,98,62);plane(g,'#c7baa0',-282,y+.065,-140,70,39);const towerX=-336,towerZ=-162;
 // The existing clock tower remains; these wings make it read as a complete palazzo frontage.
 for(const side of [-1,1]){const wing=new THREE.Group();wing.position.set(towerX-3,y,towerZ+side*22);g.add(wing);box(wing,'#c9b28d',0,6,0,13,12,34);box(wing,'#ad8d68',6.58,6,0,.24,11.5,33);for(let z=-13;z<=13;z+=6.5){box(wing,'#42575a',6.72,7.7,z,.14,1.55,1.55);column(wing,'#d9c8aa',6.9,2.2,z,.25,4.4);}box(wing,'#d9c8aa',6.9,4.45,0,.35,.35,33.5);box(wing,'#b49b77',0,12.35,0,13.6,.7,34.4);}
 // Lamps and restrained stone seating keep the square lively without blocking routes.
 for(const [x,z] of [[-319,-115],[-299,-112],[-278,-112],[-258,-117],[-318,-162],[-296,-165],[-272,-165],[-250,-158]]){box(g,'#2f3c3d',x,y+1.8,z,.1,3.6,.1);box(g,'#e4bf72',x,y+3.68,z,.34,.16,.34);}
 for(const [x,z,yaw] of [[-307,-139,0],[-279,-142,0],[-257,-139,0],[-292,-120,Math.PI/2]]){const b=new THREE.Group();b.position.set(x,y,z);b.rotation.y=yaw;g.add(b);box(b,'#66523f',0,.48,0,2.3,.12,.42);box(b,'#343f3f',0,.25,0,2.05,.5,.08);}
 // Low central well/plinth as a focal object, deliberately outside vehicle paths.
 const well=new THREE.Group();well.position.set(-285,y,-143);g.add(well);const basin=new THREE.Mesh(new THREE.CylinderGeometry(2.1,2.35,.7,18),material('#aaa18c'));basin.position.y=.35;well.add(basin);column(well,'#827969',0,1.25,0,.45,1.8);cross(well,0,2.6,0,.55);g.userData.centre={x:-282,z:-140};return g;}
function roadClearance(data,x,z){let best=Infinity;for(const r of data.roads||[]){if(['footway','path','cycleway','steps','pedestrian','tram'].includes(r.k))continue;for(let i=1;i<r.p.length;i++){const p=nearestOnSegment(x,z,r.p[i-1],r.p[i]),d=Math.hypot(p.x-x,p.z-z)-(r.w||5)/2;if(d<best)best=d;}}return best;}
function bestArcadeEdge(b,data,maxLength=30){if(!b?.p?.length)return null;let best=null;for(let i=0;i<b.p.length;i++){const a=b.p[i],q=b.p[(i+1)%b.p.length],length=Math.hypot(q[0]-a[0],q[1]-a[1]);if(length<12)continue;const dx=(q[0]-a[0])/length,dz=(q[1]-a[1])/length,mx=(a[0]+q[0])/2,mz=(a[1]+q[1])/2;let nx=-dz,nz=dx;if(pointInside(mx+nx*.4,mz+nz*.4,b.p)){nx=-nx;nz=-nz;}const x=mx+nx*1.9,z=mz+nz*1.9,clear=roadClearance(data,x,z);const score=clear+Math.min(length,maxLength)*.04;if(!best||score>best.score)best={mx,mz,dx,dz,nx,nz,length:Math.min(length,maxLength),clear,score};}return best&&best.clear>2.6?best:null;}
function porticoForBuilding(root,b,data,terrain,maxLength=28){const e=bestArcadeEdge(b,data,maxLength);if(!e)return false;const g=new THREE.Group(),x=e.mx+e.nx*1.75,z=e.mz+e.nz*1.75,y=terrain.elevation(x,z);g.position.set(x,y,z);g.rotation.y=Math.atan2(e.dx,e.dz);g.userData.passablePortico=true;g.userData.name=b.n||'Portico';const w=Math.max(12,e.length),depth=3.2;box(g,'#bba681',0,4.1,-depth*.5,w,.34,depth+.4);box(g,'#cbb896',0,4.45,-depth*.5,w+.3,.25,depth+.55);const count=Math.max(4,Math.floor(w/4));for(let i=0;i<=count;i++){const px=-w/2+i*w/count;column(g,'#d8c6a7',px,2,-depth*.92,.24,4);box(g,'#d8c6a7',px,3.95,-depth*.47,.45,.28,depth*.92);}root.add(g);return true;}
function selectivePorticos(data,terrain,landmarks){const root=new THREE.Group();root.userData.poi='passable-porticos';let count=0;const candidates=[];for(const aliases of [['Palazzo Moroni','Municipio'],['Palazzo del Bo','Università degli Studi di Padova'],['Caffè Pedrocchi','Pedrocchi'],['Palazzo della Ragione'],['Palazzo Capitanio','Capitanio']]){const b=findBuilding(data,aliases);if(b&&!candidates.includes(b))candidates.push(b);}for(const b of candidates){if(count>=6)break;if(porticoForBuilding(root,b,data,terrain,b.n?.includes('Ragione')?34:27))count++;}root.userData.porticoCount=count;return root;}
function piazzaAccents(terrain){const root=new THREE.Group();root.userData.poi='piazza-accents';for(const [x,z,w,d] of [[-145,-48,67,30],[-205,-67,54,24],[-346,-12,54,28]]){const y=terrain.elevation(x,z);const p=new THREE.Mesh(new THREE.PlaneGeometry(w,d),material('#bbae95'));p.rotation.x=-Math.PI/2;p.position.set(x,y+.045,z);p.receiveShadow=true;root.add(p);}return root;}
export function createHistoricCenter(data,terrain){const root=new THREE.Group();root.userData.poi='historic-center-upgrade';const signori=piazzaSignori(terrain),ped=pedrocchi(data,terrain),cityHall=moroni(data,terrain),bo=palazzoBo(data,terrain),porticos=selectivePorticos(data,terrain,{ped,cityHall,bo}),accents=piazzaAccents(terrain);root.add(signori,ped,cityHall,bo,porticos,accents);const groups=[signori,ped,cityHall,bo,porticos,accents];return {root,signori,pedrocchi:ped,cityHall,bo,porticos,accents,update(x,z){for(const g of groups){const c=g.userData.centre||g.position||{x:-180,z:-80};const cx=Number.isFinite(c.x)?c.x:-180,cz=Number.isFinite(c.z)?c.z:-80;g.visible=Math.hypot(x-cx,z-cz)<1050;}}};}
